import { defineTable, type Timestamp } from "@intellectual-frontiers/data/sql/typed";

/** One principal acting on behalf of another, for a time and for some permissions, never more than the one above it */
export interface DelegationRow {
  /** What identifies the delegation, made by the application */
  readonly delegationId: string;
  /** How many delegations are above it: none for the first */
  readonly depth: number;
  /** What it is for */
  readonly purpose: string;
  /** The kind of the one resource it is limited to */
  readonly resourceType: string | null;
  /** The resource it is limited to: exact, or a prefix ending `*` */
  readonly resourceId: string | null;
  /** An extra condition; the conditions of the delegations above it hold too, so a delegation can only add */
  readonly expression: string | null;
  /** The language of the condition */
  readonly expressionLanguageCode: string | null;
  /** Whether the delegate may pass it on */
  readonly redelegable: boolean;
  /** How many more delegations may be added below it; less than the one above it */
  readonly maxDepth: number;
  /** When it starts */
  readonly validFrom: Timestamp;
  /** When it ends: a delegation always ends, and never after the one above it */
  readonly expiresAt: Timestamp;
  /** Where it is */
  readonly status: "active" | "revoked" | "expired";
  /** When it was ended early */
  readonly revokedAt: Timestamp | null;
  /** Why it was ended early */
  readonly revokeReason: string | null;
  /** The tenant it is in */
  readonly tenantId: string;
  /** Who passes on what they hold */
  readonly delegatorPrincipalId: string;
  /** Who acts on their behalf */
  readonly delegatePrincipalId: string;
  /** The delegation it was made under, where it was made under one */
  readonly parentDelegationId: string | null;
  /** The first delegation of the chain, where it is not itself the first */
  readonly rootDelegationId: string | null;
  /** Who ended it early */
  readonly revokedByPrincipalId: string | null;
}

